/**
 * Canned camera frames for the simulator (FEATURES.md F10).
 *
 * Real Ring media is watermarked and fetched through the image-snapshot
 * endpoints; the simulator serves a tiny valid JPEG instead so the whole
 * pipeline (download -> classify) runs with no camera. Keeping real bytes -
 * not a placeholder string - means a future frame decoder treats them the same
 * way it will treat production frames.
 */

/** A valid 1x1 JPEG - deliberately tiny, deliberately real. */
export const CANNED_JPEG_BASE64 =
  '';

const CANNED_JPEG = new Uint8Array(Buffer.from(CANNED_JPEG_BASE64, 'base64'));

/**
 * A frame for a device. Every device gets the same bytes today; named so a
 * future night/day fixture set can swap bytes per label without touching the
 * frame source contract.
 */
export function cannedFrame(): { bytes: Uint8Array; contentType: 'image/jpeg' } {
  return { bytes: CANNED_JPEG, contentType: 'image/jpeg' };
}
